BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=public,extensions;
SELECT plan(10);
SELECT set_config('request.jwt.claims','{}',true);
INSERT INTO auth.users(id,raw_app_meta_data) VALUES ('9c7302e1-0000-4000-8000-000000000001','{}'),('9c7302e1-0000-4000-8000-000000000002','{}');
INSERT INTO public.users(id) VALUES ('9c7302e1-0000-4000-8000-000000000001'),('9c7302e1-0000-4000-8000-000000000002') ON CONFLICT DO NOTHING;
INSERT INTO public.workspaces(id,name,creator_id,personal) VALUES ('9c7302e1-0000-4000-8000-000000000010','Rollback caller scope','9c7302e1-0000-4000-8000-000000000001',false);
INSERT INTO public.workspace_members(ws_id,user_id,type) VALUES ('9c7302e1-0000-4000-8000-000000000010','9c7302e1-0000-4000-8000-000000000002','MEMBER');
SELECT ok(NOT has_function_privilege('anon','public.has_workspace_permission(uuid,uuid,text)','EXECUTE'),'rollback denies anon permission RPC execution');
SELECT ok(NOT has_function_privilege('anon','public.is_org_member(uuid,uuid)','EXECUTE'),'rollback denies anon membership RPC execution');
SELECT is((SELECT count(*) FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid IN ('public.has_workspace_permission(uuid,uuid,text)'::regprocedure,'public.is_org_member(uuid,uuid)'::regprocedure) AND a.grantee=0 AND a.privilege_type='EXECUTE'),0::bigint,'rollback does not retain PUBLIC EXECUTE');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"9c7302e1-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
SELECT ok(public.is_org_member(auth.uid(),'9c7302e1-0000-4000-8000-000000000010'),'rollback self membership works');
SELECT ok(NOT public.is_org_member('9c7302e1-0000-4000-8000-000000000001','9c7302e1-0000-4000-8000-000000000010'),'rollback denies other-user membership probing');
SELECT ok(public.has_workspace_permission('9c7302e1-0000-4000-8000-000000000010',auth.uid(),'admin'),'rollback self permission works');
SELECT ok(NOT public.has_workspace_permission('9c7302e1-0000-4000-8000-000000000010','9c7302e1-0000-4000-8000-000000000001','admin'),'rollback denies other-user permission probing');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
SELECT ok(public.is_org_member('9c7302e1-0000-4000-8000-000000000001','9c7302e1-0000-4000-8000-000000000010'),'rollback retains server cross-user membership checks');
SELECT ok(public.has_workspace_permission('9c7302e1-0000-4000-8000-000000000010','9c7302e1-0000-4000-8000-000000000001','admin'),'rollback retains server cross-user permission checks');
SELECT ok(NOT public.has_workspace_permission('9c7302e1-0000-4000-8000-000000000010','9c7302e1-0000-4000-8000-000000000001','manage_mastermind'),'rollback disables Mastermind without removing caller binding');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
